
import type { BundleComponentInput } from './BundleComponentInput.js';
import type { CategoryReferenceInput } from './CategoryReferenceInput.js';
import type { ImageInput } from './ImageInput.js';
import type { LineItemInventoryDemandInput } from './LineItemInventoryDemandInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';
import type { OrderCalculatedLineItemTaxInput } from './OrderCalculatedLineItemTaxInput.js';
import type { OrderLineItemModifierInput } from './OrderLineItemModifierInput.js';
import type { SelectedProductOptionInput } from './SelectedProductOptionInput.js';
import type { SignedMoneyInput } from './SignedMoneyInput.js';
import type { SubscribedLineInput } from './SubscribedLineInput.js';

export type OrderLineItemInput = { "base_subtotal_money": MoneyValueInput; "bundle_components"?: Array<BundleComponentInput>; "bundle_id"?: string; "categories"?: Array<CategoryReferenceInput>; "description"?: string; "discount_money": MoneyValueInput; "gift_card_purchase"?: never; "image"?: ImageInput; "inventory_snapshot"?: (({ "demands": Array<LineItemInventoryDemandInput>; "inventory_tracking": "not_tracked" | "tracked"; }) | (null)); "metadata"?: Record<string, string>; "modifier_total_money": MoneyValueInput; "modifiers"?: Array<OrderLineItemModifierInput>; "name": string; "order_line_item_id": string; "product_id"?: string; /** Masked card identities for fully funded units of this purchase line. Partial consideration does not issue a card. */ "purchased_gift_cards"?: never; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity": string; "refunded_money": MoneyValueInput; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "refunded_quantity": string; "selected_options"?: Array<SelectedProductOptionInput>; "sku"?: string; "source_type"?: "variant" | "bundle"; /** Recurring offer and cadence frozen for this line at signup. */ "subscription"?: SubscribedLineInput; /** Subscription created for this line after the order is paid. */ "subscription_id"?: string; /** Applicable active offer for a one-time line, or the offer terms frozen for a subscribed line. */ "subscription_offer"?: never; "subtotal_money": MoneyValueInput; "tax"?: OrderCalculatedLineItemTaxInput; "tax_money": MoneyValueInput; "total_money": SignedMoneyInput; "unit_price_money": MoneyValueInput; "variant_id"?: string; /** Version to send as expected_version when changing gift_card_recipient or replacing modifiers. Checkout-session reads return the checkout modifier version for modifier choices. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
